INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66752528', 66752528, 'analyze_legacy', 'Kab. Majene', 'kabkota', 'Dinas Pekerjaan Umum dan Penataan Ruang', 'Biaya Pengawasan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Sulawesi Barat, Majene (Kab.)', 3000000, 'June 2026', 'APBD', 1, 1, '0.885478158205431 Meter', '2. Lingkup Kegiatan a. Mempelajari hal-hal yang terkait dokumen kontrak pekerjaan konstruksi, termasuk pengendalian manajemen dan keselamatan lalu-lintas serta SMK3 Konstruksi, dan Dokumen Lainnya. b. Menyusun Rencana Mutu Kontrak (RMK) Pengawasan Pekerjaan. Laporan Rencana Mutu Kontrak (RMK) yaitu data lokasi, kebijakan mutu, informasi proyek, pihak–pihak yang terlibat, struktur organisasi, tugas dan tanggungjawab dalam wewenang, daftar induk bukti kerja, bagan alur pelaksanaan pekerjaan, jadwal pelaksanaan, dll yang terkait dengan rencana mutu kontrak; c. Mengawasi pelaksanaan pekerjaan konstruksi yang dilaksanakan oleh penyedia pekerjaan konstruksi agar hasil pekerjaan sesuai dengan gambar rencana dan spesifikasi pekerjaan yang ada. d. Mengukur kuantitas pekerjaan yang telah selesai dilaksanakan dan melakukan pemeriksaan untuk pembayaran akhir pekerjaan. e. Memeriksa dan menguji mutu bahan-bahan yang digunakan dan mutu hasil pekerjaannya f. Menjamin bahwa konstruksi yang sudah selesai telah memenuhi syarat. g. Memberikan saran-saran mengenai perubahan pekerjaan dan tuntutan (claims). h. Memberikan rekomendasi atas pengoperasian dan pemeliharaan peralatan yang digunakan. i. Peninjauan kembali desain, dan melaksanakan pemeriksaan gambar terlaksana. j. Melaksanakan pemeriksaan gambar terpasang / terbangun secara bertahap sesuai progres mutual check dan MC yang dicapai sampai dengan 100%. k. Melaporkan secara berkala tentang kemajuan pekerjaan dan permasalahannya, mutu pekerjaan serta status keuangan proyek, berikut kondisi lainnya yang dapat diantisipasi.', 'Tata Cara Pelaksanaan Survey Lalu Lintas, No. 01/T/BNKT/1990 b. Tata Cara Survey Kondisi Jalan Kota, No. 05/T/BNKT/1991 c. Tata Cara Survey Inventarisasi Jalan dan Jembatan Kota, No. 16/T/BNKT/1990 d. Petunjuk Perencanaan Trotoar, No. 07/T/BNKT/1990 e. Tata Cara Perencanaan Drainase Permukaan Jalan, Sk. SNI T-22-1991-03 f. Tata Cara Perencanaan Pemisah Jalan Kota, No. 14/T/BNKT/1990 g. Petunjuk Perencanaan Marka Jalan, No. 21/T/BNKT/1990 h. Tata Cara Perencanaan Persimpangan Sesederhana Jalan Perkotaan, No. 002/T/BNKT/1991 i. Standar Perencanaan Geometrik Jalan Perkotaan, Maret 1992 j. Spesifikasi Perencanaan Klasifikasi Fungsi Jalan di Wilayah Perkotaan, No. 010/T/BNKT/1990 k. Peraturan Tebal Perkerasan Lentur jalan Raya dengan Metode Analisa Komponen , SNI –1732 – 1989 F(SK BI – 2.3.26.1987) l. Perencanaan Tebal Perkerasan Lenturdan Lapis Tambah Metode ASHTO, 1993 m. Tata Cara Perencanaan Teknis Landscape Jalan, No. 033/T/BM/1996 n. Tata Cara Perencanaan Pembebanan Jembatan/Jalan Raya, SNI-1725- 1989 F (SK BI-1.3.28.1987) o. Panduan Analisa Harga Satuan, No. 028/T/BM/1995, Direktorat Jenderal Bina Marga, Departemen PekerjaanUmum p. Standar Dokumen Pengadaan dan Speifikasi Umum 2010 (Revisi 3) Untuk Pekerjaan Kontruksi Jalan dan Jembatan q. Surat Edaran (SE) Menteri Pekerjaan Umum dan Perumahan Rakyat Nomor : 02/SE/Db/2018 Tentang Spesifikasi Umum Bina Marga Tahun 2018 Revisi 2 Untuk Pekerjaan Konstruksi Jalan dan Jembatan; r. Petunjuk / Tata Cara Standar lainnya yang berhubungan dan terbaru sesuai Arahan Kemetrian PUPR, Direktorat Jenderal Bina Marga', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2982828);
