INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66751813', 66751813, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'PAS23 RUTAN KELAS II B MALINO', 'Pengadaan Belanja Pemeliharaan Gedung dan Bangunan Tahap II Untuk Kebutuhan Pemeliharaan Gedung pada Rumha Tahanan Negara Kelas IIB Malino-Sulawesi Selatan Tahun Anggaran 2026', 'Barang', 'Pengadaan Langsung', 'Sulawesi Selatan, Gowa (Kab.)', 54942500, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Bertingkat ( 1, Tahun, @ 6772000 ); 2. Tidak Bertingkat ( 1, Tahun, @ 103113000 );', 'Pengadaan Belanja Pemeliharaan Gedung dan Bangunan untuk kebutuhan pemeliharaan gedung pada Rumah Tahanan Negara Kelas IIB Malino, Provinsi Sulawesi Selatan, Tahun Anggaran 2026 ditetapkan untuk menjamin kondisi gedung dan bangunan tetap laik fungsi, aman, dan mendukung kelancaran operasional Rutan. Pengadaan ini harus mampu memastikan pelaksanaan pemeliharaan dilakukan secara tepat waktu, sesuai standar teknis, serta menjaga kualitas dan daya tahan bangunan agar dapat digunakan secara optimal. Dengan terlaksananya pemeliharaan gedung dan bangunan secara berkelanjutan, diharapkan tercipta lingkungan kerja dan hunian yang aman, nyaman, dan memenuhi standar pelayanan pemasyarakatan di Rutan Kelas IIB Malino.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2983832);
