INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66752400', 66752400, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL PENANGGULANGAN PENYAKIT', 'Pengadaan Vaksin Heksavalen Bersumber Dana Hibah GAVI Tahun Anggaran 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 56378484525, 'March 2026', 'Lainnya', 0, 0, '63.500 vial', 'Pengadaan Vaksin Heksavalen Bersumber Dana Hibah GAVI Tahun Anggaran 2026', '1. Nama: DPT-HB-Hib-IPV vaccine 2. Komposisi Vaksin: Setiap satu dosis (0,5 ml) minimal mengandung zat aktif: a. Toksoid difteri murni: ≥ 30 IU b. Toksoid tetanus murni: ≥ 40 IU c. Bakteri pertusis: ≥ 4 IU d. HBsAg: 15 mcg e. Konjugat Hib: 10 mcg f. Virus poliomyelitis type 1: Mahoney strain 40 UD (unit antigen D) g. Virus poliomyelitis type 2: MEF-1 strain 8 UD h. Virus poliomyelitis type 3: Saukett 32 UD i. Al3+ sebagai alumunium fosfat: 1.25 mg 3. Indikasi Vaksin: Mencegah penyakit Difteri, Pertusis, Tetanus, Hepatitis B, Haemophilus influenzae tipe b dan Polio tipe 1, tipe 2, dan tipe 3 4. Kemasan: a. Dikemas dalam single dose atau multi dose b. Dalam setiap kemasan ampul/vial/pouch dilengkapi dengan indikator paparan suhu panas atau Vaccine Vial Monitor (VVM) c. Dilengkapi dengan nomor batch, masa kedaluwarsa, dan brosur/leaflet yang berisi petunjuk pemakaian, indikasi, kontra indikasi, dan petunjuk penggunaan VVM dalam Bahasa Indonesia 5. Masa Kadaluarsa: Masa kadaluarsa vaksin saat diterima di pusat/ provinsi minimal 14 bulan 6. Izin Vaksin: Telah teregistrasi oleh Badan Pengawas Obat dan Makanan (BPOM) 7. Persyaratan rilis dan pendistribusian vaksin : a. Vaksin telah mendapatkan persetujuan lot release dalam bentuk sertifikat Certificate of Release (CoR) dari BPOM sebelum didistribusikan b. Dilengkapi dengan Vaccine Arrival Report (VAR) dan alat pemantau suhu secara kontinyu / data Logger', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2984119);
