INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66754716', 66754716, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Belanja Bahan dalam rangka Pedoman Mitigasi dan Komunikasi Risiko Keamanan Pangan Dalam Rangka Program Makanan Bergizi Gratis Yang Disusun', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 54800000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Kegiatan ini merupakan penyusunan Pedoman Mitigasi dan Komunikasi Risiko Keamanan Pangan dalam rangka mendukung pelaksanaan Program Makanan Bergizi Gratis (MBG). Proses penyusunan dilakukan melalui serangkaian rapat koordinasi dan pembahasan teknis bersama tim penyusun serta pemangku kepentingan terkait, hingga menghasilkan dokumen pedoman yang siap digunakan sebagai acuan pelaksanaan program.', 'Untuk mendukung kelancaran pelaksanaan kegiatan tersebut, diperlukan belanja bahan yang meliputi konsumsi rapat berupa makan dan snack bagi peserta rapat selama proses penyusunan berlangsung, serta pencetakan dan penjilidan dokumen pedoman sebagai output akhir kegiatan. Seluruh belanja bahan mengacu pada standar harga yang berlaku sesuai ketentuan peraturan perundang-undangan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2984464);
