INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66754384', 66754384, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB TAPANULI SELATAN', 'Paket pengadaan jasa outsourcing BPS Kabupaten Tapanuli Selatatan TW 2 Tahun 2025', 'Jasa Lainnya', 'E-Purchasing', 'Sumatera Utara, Tapanuli Selatan (Kab.)', 189527000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Penyedia jasa outsourcing bertanggung jawab menyediakan tenaga pendukung operasional untuk membantu kelancaran pelaksanaan tugas dan fungsi BPS Kabupaten Tapanuli Selatan pada Triwulan I Tahun 2025. Tenaga kerja yang disediakan melaksanakan pekerjaan sesuai kebutuhan satuan kerja, seperti pelayanan administrasi, pengelolaan perkantoran, dan tugas pendukung lainnya, dengan tetap mematuhi ketentuan kontrak, disiplin kerja, serta peraturan yang berlaku', 'Spesifikasi paket pengadaan jasa outsourcing meliputi penyediaan tenaga kerja pendukung operasional dan administrasi untuk BPS Kabupaten Tapanuli Selatan pada Triwulan I Tahun 2025. Tenaga kerja yang disediakan memiliki pendidikan minimal SMA/sederajat, sehat jasmani dan rohani, berdisiplin, serta mampu bekerja sama dan melaksanakan tugas perkantoran sesuai kebutuhan satuan kerja. Penyedia bertanggung jawab atas pemenuhan jumlah dan kualitas tenaga kerja, pembayaran upah dan hak-hak tenaga kerja sesuai ketentuan, serta pengawasan kinerja selama masa kontrak. Pelaksanaan pekerjaan dilakukan di Kantor BPS Kabupaten Tapanuli Selatan dengan jam kerja mengikuti ketentuan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2985859);
