INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66755301', 66755301, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'POLITEKNIK PERKERETAAPIAN INDONESIA MADIUN', 'Pengadaan Perlengkapan Taruna Tk. I', 'Barang', 'E-Purchasing', 'Jawa Timur, Madiun (Kota)', 356643000, 'March 2026', 'APBN - BADAN LAYANAN UMUM (F)', 1, 1, '1 Paket', 'Paket pekerjaan ini merupakan pengadaan perlengkapan taruna tingkat 1 berupa koper, kemeja putih model Pakaian Dinas Harian (PDH) lengan panjang, dan kemeja batik taruna. Kegiatan ini bertujuan untuk memenuhi kebutuhan perlengkapan dasar taruna dalam menunjang kegiatan pendidikan, kedisiplinan, serta keseragaman penampilan. Ruang lingkup pekerjaan meliputi penyediaan barang sesuai spesifikasi teknis yang ditetapkan, proses produksi, pengemasan, pengiriman ke lokasi, serta penyerahan dalam kondisi baik dan siap digunakan.', 'Spesifikasi pekerjaan meliputi pengadaan koper taruna berbahan hardcase yang kuat dan tahan benturan, dilengkapi roda putar (spinner), pegangan tarik, dan sistem pengunci yang aman, serta kemeja putih model Pakaian Dinas Harian (PDH) lengan panjang berbahan poliester warna putih dengan kerah lipat, kancing depan penuh, dan dua saku dada, serta kemeja batik taruna lengan panjang berbahan poliester dengan kombinasi warna dongker dan ungu tua bermotif batik warna putih, menggunakan kerah berdiri (mandarin collar), satu saku dada, serta sistem kancing tertutup (hidden placket) sehingga kancing tidak terlihat dari luar, dengan seluruh produk memiliki kualitas baik, jahitan rapi, tidak cacat, dan sesuai desain yang ditetapkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2985969);
