INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66756904', 66756904, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'TENAGA PENYUSUNAN LAPORAN PENGADMINISTRASIAN DOKUMEN ANALISIS KEUANGAN DAN PERPAJAKAN PADA KEGIATAN PELAYANAN ADMINISTRASI', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 84214840, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Ruang lingkup kegiatan Tenaga Penyusunan Laporan Pengadministrasian Dokumen Analisis Keuangan dan Perpajakan pada Kegiatan Pelayanan Administrasi mencakup dukungan teknis operasional yang bersifat pendukung terhadap pelaksanaan tugas Direktorat Industri, Perdagangan, dan Peningkatan Investasi, khususnya dalam pengelolaan administrasi keuangan dan perpajakan. Dukungan tersebut dilaksanakan berdasarkan arahan dan supervisi ASN penanggung jawab, dengan lingkup kegiatan sebagai berikut: 1. Penyusunan dan penyiapan laporan administrasi keuangan, meliputi pengumpulan, pengolahan, pengklasifikasian, serta perapihan data dan dokumen keuangan kegiatan. 2. Pengadministrasian dokumen analisis keuangan, termasuk pra-verifikasi kelengkapan dokumen, pencocokan data lintas dokumen perencanaan, pelaksanaan, dan pelaporan, serta penyiapan bahan pendukung analisis administrasi keuangan dalam proses penganggaran dan pelaporan. 3. Pengelolaan administrasi perpajakan kegiatan, yang mencakup pengumpulan dan verifikasi dokumen pajak, pengadministrasian bukti potong dan bukti setor, pencatatan data perpajakan, serta penyiapan bahan laporan perpajakan sesuai ketentuan peraturan perundang-undangan. 4. Pemutakhiran dan konsolidasi data keuangan dan perpajakan, berdasarkan aplikasi dan sistem administrasi pemerintah yang relevan, sepanjang bersifat teknis operasional dan tidak mencakup kewenangan pengesahan atau pengambilan keputusan. 5. Pengelolaan dokumentasi dan arsip administrasi keuangan dan perpajakan secara tertib dan sistematis sebagai bahan pendukung akuntabilitas dan pemeriksaan. 6. Dukungan koordinasi teknis-operasional administrasi keuangan dan perpajakan dengan unit kerja terkait dalam rangka kelancaran pelayanan administrasi, sesuai penugasan ASN penanggung jawab. 7. Pelaksanaan tugas pendukung lainnya yang relevan dengan penyusunan laporan dan pengadministrasian dokumen analisis keuangan dan perpajakan sepanjang bersifat teknis operasional. Seluruh ruang lingkup pekerjaan tersebut berada pada ranah layanan dukungan non-kedinasan dan tidak termasuk dalam kategori tugas, fungsi, maupun kewenangan jabatan struktural atau fungsional Aparatur Sipil Negara (ASN). Pelaksanaan pekerjaan tidak dimaksudkan untuk mengisi, menggantikan, ataupun menjalankan peran jabatan ASN, serta tidak mencakup pengambilan keputusan kedinasan, penandatanganan dokumen resmi, kewenangan penetapan kebijakan, maupun fungsi lain yang secara regulatif menjadi domain ASN. Dalam pelaksanaan pekerjaan ini, Penyedia dan/atau Tenaga Ahli/Tenaga Pendukung yang ditugaskan tidak berhak dan tidak memperoleh fasilitas yang melekat pada ASN. Penyedia dan/atau tenaga yang ditugaskan tidak diberikan dan tidak diperkenankan menerima antara lain: • Barang Milik Negara (BMN), baik untuk kepemilikan maupun penggunaan pribadi; • Tunjangan Hari Raya (THR) dan/atau Gaji ke-13; • Kepesertaan atau pembiayaan BPJS Kesehatan dan BPJS Ketenagakerjaan yang bersumber dari anggaran negara pada Kementerian/Lembaga; • Fasilitas layanan kesehatan atau klinik yang diperuntukkan bagi ASN; dan • Fasilitas lainnya yang secara regulatif hanya diberikan kepada ASN atau pegawai pemerintah dengan perjanjian kerja. Penugasan tenaga oleh Penyedia tidak menimbulkan hubungan kepegawaian dengan Kementerian/Lembaga dan tidak menimbulkan hak, ekspektasi, maupun klaim dalam bentuk apa pun terkait pengangkatan sebagai ASN, PPPK, atau pegawai pemerintah lainnya di kemudian hari. Seluruh hak dan kewajiban ketenagakerjaan tenaga yang ditugaskan sepenuhnya menjadi tanggung jawab Penyedia sesuai dengan ketentuan peraturan perundang-undangan yang berlaku.', 'Pelaksanaan kegiatan Tenaga Penyusunan Laporan Pengadministrasian Dokumen Analisis Keuangan dan Perpajakan pada Kegiatan Pelayanan Administrasi menghasilkan keluaran berupa laporan pengadministrasian dokumen dan perpajakan yang disusun secara periodik bulanan. Keluaran tersebut disusun sebagai bentuk pertanggungjawaban pelaksanaan dukungan teknis operasional administrasi keuangan dan perpajakan, sekaligus sebagai instrumen pemantauan kinerja dan akuntabilitas pelaksanaan kegiatan di lingkungan Direktorat Industri, Perdagangan, dan Peningkatan Investasi. Setiap keluaran mencerminkan hasil pelaksanaan kegiatan pengumpulan, pengolahan, verifikasi, dan pengadministrasian dokumen keuangan dan perpajakan sesuai periode berjalan, serta disusun secara berkesinambungan dan kumulatif sepanjang tahun anggaran. Penetapan jadwal dan bobot keluaran dilakukan untuk memastikan ketercapaian target kinerja secara bertahap, ketepatan waktu penyampaian laporan, serta keterpaduan antara proses administrasi, pengelolaan perpajakan, dan pelaporan kegiatan. Adapun rincian keluaran, jadwal penyampaian, dan bobot penilaian kinerja disajikan dalam tabel berikut.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2988619);
