INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66759084', 66759084, 'analyze_legacy', 'Kementerian Pariwisata', 'central', 'DEPUTI BIDANG PENGEMBANGAN PENYELENGGARA KEGIATAN', 'Belanja Jasa Lainnya (Pendukungan Live Streaming Program Kejuaraan Nasional Mandalika Racing Series 2026)', 'Jasa Lainnya', 'E-Purchasing', 'Nusa Tenggara Barat, Lombok Tengah (Kab.)', 1600000000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 0, 0, '1 Paket', 'Mandalika Racing Series adalah Kejuaraan Nasional Balap Motor kategori Sportbike yakni Junior Sport U-15, 150cc, 250cc dan Supersport 600cc serta kelas pendukung Underbone 150 U-25, 250 Community, Supersport/Superbike Community. Tujuan Kegiatan Mandalika Racing Series bertujuan mengembangkan bakat para pembalap muda di seluruh Indonesia dan mencari talenta para pembalap muda untuk berajang di motogp. Pada tahun 2026 ini, Kejurnas Mandalika Racing Series digelar selama 5 seri pada 24 – 26 April, 19 – 21 Juni, 7 – 9 Agustus, 18 – 20 September dan 6 – 8 November 2026. Pada tahun ini, Kejurnas MRS kembali dapat dinikmati oleh masyarakat umum melalui penayangan di kanal youtube Mandalika Racing Series dan channel media lain yang bekerjasama dengan penyelenggara.', 'Kegiatan Mandalika Racing Series (MRS) terdiri dari : Kementerian Pariwisata akan mendukung 3 paket promosi event Kejurnas MRS melalui live streaming dengan penyediaan tenaga ahli, peralatan live streaming profesional seperti kamera, audio, jaringan internet dan peralatan pendukung lainnya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2989880);
